import{_ as u,a0 as p,w as a,s as x,I as i,x as o,a1 as t,A as r,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"讓Linux賓至如歸 | LCTT x X-CMD","titleTemplate":false,"description":"讓Linux賓至如歸 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"讓Linux賓至如歸 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"讓Linux賓至如歸 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Making Linux Feel at Home","title":"讓Linux賓至如歸","tag":"201406","desc":""},"relativePath":"201406/Making Linux Feel at Home.md","filePath":"[post].md"}'),s={name:"201406/Making Linux Feel at Home.md"};function d(L,n,m,f,w,C){const l=p("Link");return a(),x("div",null,[n[23]||(n[23]=i("h1",{id:"讓linux賓至如歸",tabindex:"-1"},[o("讓Linux賓至如歸 "),i("a",{class:"header-anchor",href:"#讓linux賓至如歸","aria-label":"Permalink to “讓Linux賓至如歸”"},"​")],-1)),n[24]||(n[24]=i("p",null,[i("strong",null,"採用小企鵝不管是對於小企業還是大企業而言，都是一個明智的選擇。Linux曾經被認為是業餘愛好者的操作系統，但是經歷了很長一段歷程後，現在它成了企業級系統。它很穩定，而且很安全。Linux易於定製，而且有龐大的社區提供幫助。這只是遷移到Linux桌面的部分理由。")],-1)),n[25]||(n[25]=i("p",null,[i("img",{src:"http://www.linuxinsider.com/images/rw979454/linux-migration.jpg",alt:""})],-1)),n[26]||(n[26]=i("p",null,"遷移到一個不同的系統，從來都不是件容易的事。繼續開着窗户（Windows），或吃着蘋果（MacIntosh）可能是個令人沮喪且代價高昂的體驗。花錢升級新的硬件來趕上高貴的新軟件時髦，這往往是毫無價值的做法。",-1)),n[27]||(n[27]=i("p",null,"在家裏或一個小型的辦公環境中運行一個Linux發行版，這是個有益的嘗試，它可以帶來開支的節約和效率的提升。對於企業環境而言，採用Linux服務器系統來替代微軟基礎架構常常是個明智的商業選擇。",-1)),n[28]||(n[28]=i("p",null,"然而，放棄熟悉操作系統下的舒適環境的過程看起來比實際更具挑戰性。個人用户和中小型企業可以分階段遷移到Linux桌面。軟件是免費的，而用户已有的硬件是可以支持Window和Linux架構的。",-1)),n[29]||(n[29]=i("p",null,"許多更大型的企業已經跑起了它們自己的Linux服務器倉庫和完整的Linux桌面應用，這裏它更容易適應。基於雲的軟件的使用使得辦公室人員在使用他們的工作站工作時意識不到有很大的改變。",-1)),i("p",null,[n[1]||(n[1]=o("“是否遷移到Linux取決於使用情況。如果在家裏使用，或者從事開發，那麼你會想使用Linux中所有可用的功能。那是沒腦子的想法。遷移到另外一個操作系統從來沒有一帆風順的。沒有哪種使用情況可以適合所有場合，它取決於用户基礎。“麥克 瓦伊塔爾，",-1)),t(l,{href:"http://www.talkpointcommunications.com/"},{default:r(()=>[...n[0]||(n[0]=[o("Talkpoint",-1)])]),_:1}),n[2]||(n[2]=o("首席技術官，告訴LinuxInsider。",-1))]),n[30]||(n[30]=i("p",null,"在中小型企業中和企業客户一起工作，瓦伊塔爾發現，利用新技術的個人用户和公司領導者的數量在增長，這些新技術將他們吸引到Linux中來。",-1)),n[31]||(n[31]=i("h3",{id:"舒適度期望值",tabindex:"-1"},[o("舒適度期望值 "),i("a",{class:"header-anchor",href:"#舒適度期望值","aria-label":"Permalink to “舒適度期望值”"},"​")],-1)),n[32]||(n[32]=i("p",null,"這些Linux技術之一就是Chrome OS，還有現在由基於Linux的Chrome操作系統驅動的廉價筆記本。",-1)),n[33]||(n[33]=i("p",null,"由於用户已經熟悉Google的Chrome瀏覽器，或者開源的Chronium瀏覽器項目，使用Chromebook或者基於雲的運載系統使得遷移到Linux變得小菜一碟。",-1)),i("p",null,[n[4]||(n[4]=o("“忽略使用的操作系統，其中一個問題是瀏覽器的能力。我們已經發現，用户85%的時間花在瀏覽器中”",-1)),t(l,{href:"http://www.splashtop.com/"},{default:r(()=>[...n[3]||(n[3]=[o("Splashtop",-1)])]),_:1}),n[5]||(n[5]=o("的共同創立者及產品管理高級副總裁托馬斯.鄧這樣對LinuxInsider説。",-1))]),n[34]||(n[34]=e('<p>鄧發現，那些有着快速學習曲線、能適應較新技術的人對此越來越有興趣。人們使用多種多樣的產品。因此遷移到一個與他們在其它設備上使用過的系統類似的系統，會使得遷移更平穩。</p><h3 id="chrome迎合潮流" tabindex="-1">Chrome迎合潮流 <a class="header-anchor" href="#chrome迎合潮流" aria-label="Permalink to “Chrome迎合潮流”">​</a></h3><p>移動設備用户，不管是在家中還是工作中，越來越精通Linux，而他們根本不知道這是個什麼系統。他們在幾個操作系統間切換。伴隨着熟練程度的提高，開源環境也越發讓人感覺舒適。通過雲平台來分發跨平台軟件，這是一個附加的遷移措施。</p><p>“Google正在做的是與辦公套件相關的一些真正有趣的事情。Google現在正在它的Chrome OS上敞開大門。”瓦伊塔爾説。</p><p>對於關閉窗户（Windows），敞開大門（Chrome OS），一個很好的例子是它的公司內部使用Chrome驅動的工具。例如，Talkpoint使用ChromeBox設備。</p><p>“那就為多媒體團隊和傳統的AV用户敞開了大門。我們看到該技術上的很多進展。”瓦伊塔爾解釋説。</p><h3 id="平板打破傳統" tabindex="-1">平板打破傳統 <a class="header-anchor" href="#平板打破傳統" aria-label="Permalink to “平板打破傳統”">​</a></h3><p>另外一個Linux設備為遷移到桌面OS鋪平道路的例子是安卓系統的流行。加上這個為智能手機和平板電腦改良的Linux發行版。</p><p>“對於遷移到Linux的人而言，人們對平板界面感到很舒服，尤其是在對Windows 8界面感到不滿之後。我認識的每個人都試着回到Windows 7。”瓦伊塔爾説。</p><h3 id="雲計算具有linux影響力" tabindex="-1">雲計算具有Linux影響力 <a class="header-anchor" href="#雲計算具有linux影響力" aria-label="Permalink to “雲計算具有Linux影響力”">​</a></h3><p>人們希望使用像MS Offcie這樣熟悉的生產工具來進行文字處理。而在Windows平台上，開源產品不怎麼被人熟知。因此，在開始遷移到完整的Linux桌面之前，先整合開源工具到原有平台會很有幫助。鄧解釋道。</p><p>隨着Google Docs和Google Chrome瀏覽器的流行，Windows用户不知道開源的趨勢正在發生改變。他指出。</p><p>“讓遷移到Linux變得方便的另外一條路是遷移到雲端，使用雲端應用。”鄧説。“對用户進行教育，是將用户遷移到Linux的最有效的方式。Chromebook正大量被採用，這是一條遷移到Linux便捷的道路。”</p><h3 id="小企鵝威猛" tabindex="-1">小企鵝威猛 <a class="header-anchor" href="#小企鵝威猛" aria-label="Permalink to “小企鵝威猛”">​</a></h3>',14)),i("p",null,[n[7]||(n[7]=o("聘請Tux，Linux的吉祥物小企鵝，對於小企業和大企業來説都是明智的選擇。它是一個成熟、穩定而又靈活的操作系統，絕對可以幫你幹活。據肖恩.塞樂，",-1)),t(l,{href:"http://www.visionsolutions.com/"},{default:r(()=>[...n[6]||(n[6]=[o("視覺解決方案",-1)])]),_:1}),n[8]||(n[8]=o("高級產品經理説。",-1))]),n[35]||(n[35]=i("p",null,"“對於小型商業公司，運行Linux來替代其它操作系統是令人信服的選擇，而且也帶來優勢，當然這取決於你的公司的需求。”塞樂告訴LinuxInsider。",-1)),n[36]||(n[36]=i("p",null,"它曾經被認為是業餘愛好者的操作系統，但是經歷了很長一段歷程後，現在它成了企業級系統。它很穩定，而且很安全。Linux易於定製，而且有龐大的社區提供幫助。這只是遷移到Linux桌面的部分理由。",-1)),n[37]||(n[37]=i("h3",{id:"商業加分",tabindex:"-1"},[o("商業加分 "),i("a",{class:"header-anchor",href:"#商業加分","aria-label":"Permalink to “商業加分”"},"​")],-1)),n[38]||(n[38]=i("p",null,"利用更多的社區支持模式可以節約成本，塞樂説。Linux可以獲得免費的社區支持，也可以付費訂閲完整的技術支持。一些Linux版本也有硬件和軟件認證這些東西，這些對於某些工作環境是很重要的。",-1)),i("p",null,[n[10]||(n[10]=o("例如，小型商業公司和大型企業可以完整地免費運行像CentOS或者OpenSuse這樣的發行版，或者也可以從",-1)),t(l,{href:"http://www.redhat.com/"},{default:r(()=>[...n[9]||(n[9]=[o("Red Hat",-1)])]),_:1}),n[11]||(n[11]=o("或者Suse來整合付費的版本。即便是一個完整的訂閲服務，Linux也比Windows或者傳統的Unix提供了更低的總擁有成本，以及更好的投資回報，塞樂解釋道。",-1))]),n[39]||(n[39]=e('<p>“我相信，讓小型企業來切身體驗一下Linux很有意義。”塞樂補充道，“由於在社區以及像IBM和Red Hat這樣的公司的幫助下，開源軟件總體上正以快速的步伐幫助推動革新，Linux有一個光明的前途。”</p><h3 id="小心爽一把" tabindex="-1">小心爽一把 <a class="header-anchor" href="#小心爽一把" aria-label="Permalink to “小心爽一把”">​</a></h3><p>操作系統在家庭和工作場所有不同的忠實用户。就拿BDNA的CTO沃克.懷特來説吧。他在家裏使用Linux作為桌面操作系統，但是他的家人卻對他熱衷的東西並不買賬。</p><p>“我的家人用Mac之類的。他們盲目追隨市場營銷和功能炒作，而根本不考慮性能之類的東西。我在家裏進行一個人的聖戰，試着策反更多的人來加入Linux陣營。”懷特告訴LinuxInsider。</p><p>在他的公司裏有類似的死忠派在奮鬥，他説道，他公司裏Linux桌面使用並不普遍 —— 但他們為Linux在工作中更廣泛地部署打下了基礎。</p><p>BDNA在內部使用Google應用很多。公司也在把越來越多的東西遷移到基於雲計算的產品中。無論如何，這會給籌備中的工作更多的支持。</p><p>“當我切換到想OpenOffice這樣的應用時，該操作必須真正實現無縫操作以捕獲更多人的心。從純市場角度看，開發者需要稍稍改變一下游戲規則。蘋果贏得了年輕孩子和30歲年輕一代的心。我經常在我公司聽到這樣的想法。”他説。</p><h3 id="小企鵝對戰蘋果" tabindex="-1">小企鵝對戰蘋果 <a class="header-anchor" href="#小企鵝對戰蘋果" aria-label="Permalink to “小企鵝對戰蘋果”">​</a></h3><p>增加新的硬件設備是高端的MacBook Pro的特點，懷特解釋道。儘管他們主要使用的工具是在線工具，BDNA的職員還是想要華而不實的，高度宣傳的硬件。</p><p>為了打破這種觀念，他不得不將操作系統和硬件的功能分離。戰役的一部分是將用户與操作系統本身隔離。而這隻有在企業同時有在線和離線的生產力應用程序才會發生，據懷特説。</p><p>“即使是使用文件管理器這樣簡單的事情，也應該將注意力放在操作系統允許我們在我們使用的應用裏頭做什麼，而不是操作系統本身。”他説。</p><h3 id="爽到極點" tabindex="-1">爽到極點 <a class="header-anchor" href="#爽到極點" aria-label="Permalink to “爽到極點”">​</a></h3><p>操作系統多大程度上控制計算機用户？這個問題對於遷移到Linux而言很關鍵，懷特説。</p><p>想想Chromebook以及安卓手機和平板的不斷成功，消費者真的需要知道他們正在運行Linux麼？</p><p>“我認為遷移到Linux以及Linux在家裏成功的關鍵在於，我們可以在線做多少事情。”懷特説，“因為我在家裏使用Linux，所以我看到了其中的優勢。”</p><p>你是否啓用家庭消費者層面的設置，或是轉向家庭或小企業用户設置，重點在於用户可以兼容他們使用的工具和功能。這裏頭包括像共享和創建文檔，以及與之相關的事情，他説明道。</p><h3 id="遷移措施" tabindex="-1">遷移措施 <a class="header-anchor" href="#遷移措施" aria-label="Permalink to “遷移措施”">​</a></h3><p>對於市場而言，軟件和硬件生產商需要減少對操作系統的關注。例如，Chromebook正以蘋果銷售MacBook類似的方式獲得大眾認可。Google與其説是在販賣Linux操作系統，倒不如説它是在銷售應用，懷特回答道。</p><p>“開發者真正需要做的是改變工作重點，讓用户和Linux相處融洽，而不是讓他們停留在使用非Windows，或者非Mac操作系統的躊躇上。不管你用什麼，必須可以讓它做你想讓它做的事。像Chromebook這樣的事物正是秉承了這樣的觀點，將Linux操作系統本身掩蓋了起來。”他指出。</p><p>計算機生產商必須首先開始打破“它是Windows”或者“它是Mac”這樣的模式。到那個時候，遷移到Linux的數量才會大幅攀升，懷特總結道。</p><p>“這無關操作系統品牌，”他説，“而在於運行該操作系統的設備所能做的事。”</p><hr>',22)),i("p",null,[n[13]||(n[13]=o("via: ",-1)),t(l,{href:"http://www.linuxinsider.com/story/80415.html"},{default:r(()=>[...n[12]||(n[12]=[o("http://www.linuxinsider.com/story/80415.html",-1)])]),_:1})]),i("p",null,[n[16]||(n[16]=o("譯者：",-1)),t(l,{href:"https://github.com/GOLinux"},{default:r(()=>[...n[14]||(n[14]=[o("GOLinux",-1)])]),_:1}),n[17]||(n[17]=o(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:r(()=>[...n[15]||(n[15]=[o("wxy",-1)])]),_:1})]),i("p",null,[n[20]||(n[20]=o("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[18]||(n[18]=[o("LCTT",-1)])]),_:1}),n[21]||(n[21]=o(" 原創翻譯，",-1)),t(l,{href:"http://linux.cn/"},{default:r(()=>[...n[19]||(n[19]=[o("Linux中國",-1)])]),_:1}),n[22]||(n[22]=o(" 榮譽推出",-1))])])}const h=u(s,[["render",d]]);export{k as __pageData,h as default};
